+// logClientCertAudit logs the client certificate subject and serial number in a structured JSON audit log at session start.
+func (s *ProxyServer) logClientCertAudit(r *http.Request, event string) {
+	if r == nil || r.TLS == nil || len(r.TLS.PeerCertificates) == 0 {
+		return
+	}
+	cert := r.TLS.PeerCertificates[0]
+	logEntry := map[string]interface{}{
+		"event": event,
+		"client_cert_subject": cert.Subject.String(),
+		"client_cert_serial": cert.SerialNumber.String(),
+	}
+	if len(cert.DNSNames) > 0 {
+		logEntry["client_cert_dns_sans"] = cert.DNSNames
+	}
+	if len(cert.EmailAddresses) > 0 {
+		logEntry["client_cert_email_sans"] = cert.EmailAddresses
+	}
+	if len(cert.IPAddresses) > 0 {
+		var ips []string
+		for _, ip := range cert.IPAddresses {
+			ips = append(ips, ip.String())
+		}
+		logEntry["client_cert_ip_sans"] = ips
+	}
+	jsonData, _ := json.Marshal(logEntry)
+	s.log.Info("proxy.audit", zap.String("audit", string(jsonData)))
+}
+
+// checkClientCertSanSuffix enforces the SAN suffix allow-list policy. Returns error if not allowed.
+func (s *ProxyServer) checkClientCertSanSuffix(state *tls.ConnectionState) error {
+	if len(s.cfg.ClientCertSanSuffixAllowList) == 0 {
+		return nil // No allow-list enforced
+	}
+	if state == nil || len(state.PeerCertificates) == 0 {
+		return errors.New("no client certificate presented")
+	}
+	cert := state.PeerCertificates[0]
+	// Collect all SANs (DNS, Email, IP as string)
+	var sans []string
+	sans = append(sans, cert.DNSNames...)
+	sans = append(sans, cert.EmailAddresses...)
+	for _, ip := range cert.IPAddresses {
+		sans = append(sans, ip.String())
+	}
+	for _, san := range sans {
+		for _, suffix := range s.cfg.ClientCertSanSuffixAllowList {
+			if strings.HasSuffix(san, suffix) {
+				return nil // Allowed
+			}
+		}
+	}
+	return fmt.Errorf("client certificate SAN does not match allowed suffixes: %v", s.cfg.ClientCertSanSuffixAllowList)
+}
+
